class RoroElement{static cache={};constructor(eltType,id=null,prefixId="",elementArguments={},useCache=!1){this.eltType=eltType,this.id=id||(crypto?.randomUUID?.()??Math.random().toString(36).slice(2)),prefixId&&(this.id=`${prefixId}-${this.id}`),this.ajaxRoute=RoroElement.getAjaxRoute(eltType),this.elementArguments=elementArguments,this.useCache=useCache,this.ready=this.registerElement()}static getAjaxRoute(eltType){return"/roro/ajax/get/"+eltType}async registerElement(){await new Promise(resolve=>setTimeout(resolve,0));const existing=$("#"+this.id);if(existing.length)return this.finalize(existing,!0);if(this.useCache&&RoroElement.cache[this.eltType])return this.finalize(RoroElement.cache[this.eltType].clone(!0,!0),!1);const $elt=await this.loadElement();return this.useCache&&(RoroElement.cache[this.eltType]=$elt.clone(!0,!0)),this.finalize($elt,!1)}finalize(elt,isFromDom){return this.elt=isFromDom?elt:elt.attr("id",this.id),this.isFromDom=isFromDom,this.registerEvents(),this}loadElement(){return new Promise((resolve,reject)=>{$.ajax({url:this.ajaxRoute,type:"GET",data:this.elementArguments,success:data=>resolve($(data)),error:(xhr,status,error)=>reject(new Error(`Ajax element creation error: ${error}`))})})}registerEvents(){}syncDom(){}}
